exec(open('extract.py').read())
import numpy as np
from PIL import Image,ImageDraw
from scipy import ndimage as ndi

def color_mask(a,color):
 r,g,b=[a[:,:,i].astype(float) for i in range(3)]
 if color=='black':return (r<180)&(g<180)&(b<180)&(np.maximum.reduce([r,g,b])-np.minimum.reduce([r,g,b])<35)
 if color=='red':return (r>g+35)&(r>b+35)&(g<225)
 if color=='green':return (g>r+25)&(g>b+25)&(r<230)
 if color=='blue':return (b>r+35)&(b>g+35)&(r<230)
 if color=='magenta':return (r>g+25)&(b>g+25)&(g<230)

def holes(n,color,roi,minsize=1,maxsize=100):
 a=np.array(Image.open(f'images/fig_{n:03}.png').convert('RGB'))
 mask=color_mask(a,color)
 l,r,t,b=roi; ok=np.zeros(mask.shape,bool);ok[t:b,l:r]=1;mask &= ok
 # tolerate antialiased ring outlines
 filled=ndi.binary_fill_holes(mask)
 lab,num=ndi.label(filled&~mask)
 pts=[]
 for sl in ndi.find_objects(lab):
  if sl is None:continue
  y,x=sl; ar=(filled&~mask)[sl];size=ar.sum()
  if minsize<=size<=maxsize:
   yy,xx=np.where(ar);pts.append((float(x.start+xx.mean()),float(y.start+yy.mean())))
 return sorted(pts)
def overlay(n,allpts):
 im=Image.open(f'images/fig_{n:03}.png').convert('RGB');d=ImageDraw.Draw(im)
 for pts in allpts:
  for x,y in pts:d.ellipse((x-2,y-2,x+2,y+2),fill='orange')
 im.save(f'check{n}.png')
for n,roi in [(16,(90,540,120,360)),(74,(51,402,250,558)),(76,(195,858,45,640)),(79,(139,837,220,1050)),(9,(117,706,95,488)),(96,(117,706,30,475))]:
 arr=[]
 for c in (['black'] if n==16 else ['black','red','green','blue'] if n in [74,76] else ['black','red','blue'] if n==79 else ['black','red']):
  pts=holes(n,c,roi,2,90);arr.append(pts);print(n,c,len(pts))
 overlay(n,arr)
